function validate(input) {
  if (input.some(v => !Number.isInteger(v) || v < 1 || v > 8)) return 'Every coordinate is a whole number from 1 to 8.';
  const [a, b, c, d, e, f] = input;
  const squares = new Set([a * 9 + b, c * 9 + d, e * 9 + f]);
  if (squares.size !== 3) return 'The three pieces must stand on different squares.';
  return null;
}

