function minMovesToCaptureTheQueen(a, b, c, d, e, f) {
  // The rook shares the queen's row; the bishop blocks only if it sits between them on that row.
  if (a === e) {
    const bishopBetween = c === a && (d - b) * (d - f) < 0;
    if (!bishopBetween) return 1;
  }
  // The rook shares the queen's column.
  if (b === f) {
    const bishopBetween = d === b && (c - a) * (c - e) < 0;
    if (!bishopBetween) return 1;
  }
  // The bishop shares the queen's down-right diagonal (row - column is constant).
  if (c - d === e - f) {
    const rookBetween = a - b === c - d && (a - c) * (a - e) < 0;
    if (!rookBetween) return 1;
  }
  // The bishop shares the queen's up-right diagonal (row + column is constant).
  if (c + d === e + f) {
    const rookBetween = a + b === c + d && (a - c) * (a - e) < 0;
    if (!rookBetween) return 1;
  }
  // No direct capture: the rook can always do it in two moves.
  return 2;
}

