function minMovesToCaptureTheQueen(a, b, c, d, e, f) {
  // Breadth-first search over the positions of both white pieces.
  const rookDirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  const bishopDirs = [[1, 1], [1, -1], [-1, 1], [-1, -1]];
  const key = state => state.join(',');
  let frontier = [[a, b, c, d]];
  const seen = new Set([key(frontier[0])]);
  for (let moves = 1; moves <= 10; moves++) {
    const next = [];
    for (const [rr, rc, br, bc] of frontier) {
      const pieces = [[rr, rc, rookDirs, true], [br, bc, bishopDirs, false]];
      for (const [row, col, dirs, isRook] of pieces) {
        const [or, oc] = isRook ? [br, bc] : [rr, rc];
        for (const [dr, dc] of dirs) {
          let r = row + dr, cc = col + dc;
          while (r >= 1 && r <= 8 && cc >= 1 && cc <= 8) {
            if (r === e && cc === f) return moves;
            if (r === or && cc === oc) break;
            const state = isRook ? [r, cc, br, bc] : [rr, rc, r, cc];
            if (!seen.has(key(state))) { seen.add(key(state)); next.push(state); }
            r += dr; cc += dc;
          }
        }
      }
    }
    frontier = next;
  }
  return -1;
}

