function generate(rand, size) {
  const pick = () => 1 + Math.floor(rand() * 8);
  for (;;) {
    const queen = [pick(), pick()];
    let rook = [pick(), pick()];
    let bishop = [pick(), pick()];
    const mode = Math.floor(rand() * 3);
    // Lines through the queen make captures and blockers common.
    if (mode === 1) rook = rand() < 0.5 ? [queen[0], pick()] : [pick(), queen[1]];
    if (mode === 2) {
      const step = Math.floor(rand() * 15) - 7;
      bishop = rand() < 0.5 ? [queen[0] + step, queen[1] + step] : [queen[0] + step, queen[1] - step];
    }
    if (rand() < 0.4) {
      // Try to drop the other piece between the attacker and the queen.
      const from = mode === 2 ? bishop : rook;
      const t = rand();
      const between = [Math.round(from[0] + (queen[0] - from[0]) * t), Math.round(from[1] + (queen[1] - from[1]) * t)];
      if (mode === 2) rook = between; else bishop = between;
    }
    const cells = [rook, bishop, queen];
    if (cells.some(([r, c]) => r < 1 || r > 8 || c < 1 || c > 8)) continue;
    const keys = new Set(cells.map(([r, c]) => r * 9 + c));
    if (keys.size === 3) return [rook[0], rook[1], bishop[0], bishop[1], queen[0], queen[1]];
  }
}
